public class WGMagicData {
    public static void add(WGData d,CachedOutput c,List<CompletableFuture<?>> jobs,List<Object> research,List<Object> pages){
        research.add(map("key","witchinggadgets:WGPOTIONS","category","WITCHGADG","displayColumn",8,"displayRow",0,"complexity",0,"aspects",map(),"isRound",true,"isAutoUnlock",true,"pageCount",2,"icon_resource","witchinggadgets:textures/gui/research/icon_potioneffects.png"));pages.add(map("key","witchinggadgets:WGPOTIONS","pages",List.of(text("WGPOTIONS.1"),text("WGPOTIONS.2"))));
        enchant(d,c,jobs,research,pages,"invisible_gear","INVISIBLEGEAR","invisgear",-10,1,Map.of("praecantatio",2,"vitreus",4,"tenebrae",4),Map.of("tenebrae",4,"vitreus",8,"praecantatio",8),2,List.of(part("minecraft:quartz"),part("thaumcraft:salis_mundus"),part("witchinggadgets:gemstone_dust")));
        enchant(d,c,jobs,research,pages,"unveiling","UNVEILING","unveiling",-10,2,Map.of("praecantatio",2,"sensus",4,"lux",4),Map.of("lux",4,"sensus",8,"praecantatio",8),2,List.of(part("minecraft:golden_carrot"),part("thaumcraft:salis_mundus")));
        enchant(d,c,jobs,research,pages,"stealth","STEALTH","stealth",-9,3,Map.of("praecantatio",2,"motus",4,"tenebrae",4),Map.of("motus",6,"tenebrae",8,"praecantatio",8),2,List.of(potion("invisibility"),part("thaumcraft:salis_mundus")));
        enchant(d,c,jobs,research,pages,"backstab","BACKSTAB","backstab",-11,4,Map.of("praecantatio",2,"telum",4,"tenebrae",4),Map.of("telum",12,"tenebrae",8,"praecantatio",4),3,List.of(part("minecraft:iron_sword"),potion("invisibility"),part("thaumcraft:salis_mundus")));
        enchant(d,c,jobs,research,pages,"ride_protect","RIDEPROTECT","rideprotect",-11,0,Map.of("praecantatio",2,"vinculum",4,"tutamen",4),Map.of("tutamen",12,"vinculum",8,"praecantatio",4),3,List.of(part("thaumcraft:salis_mundus"),part("minecraft:piston"),part("minecraft:piston")));
    }
    private static void enchant(WGData d,CachedOutput c,List<CompletableFuture<?>> jobs,List<Object> research,List<Object> pages,String id,String old,String icon,int x,int y,Map<String,Integer> researchAspects,Map<String,Integer> costs,int instability,List<Object> parts){String key="ENCH_"+old;var enchant=WGMagic.ENCHANTS.get(id).get();int xp=Math.max(1,enchant.getMinCost(1)/3);jobs.add(d.save(c,"data/witchinggadgets/recipes/enchant_"+id+".json",map("type","witchinggadgets:gear_enchantment","research","witchinggadgets:"+key,"enchantment","witchinggadgets:"+id,"base_xp",xp,"aspects",costs,"instability",instability,"components",parts)));var display=new ArrayList<Object>();for(var part:parts){var p=JSON.toJsonTree(part).getAsJsonObject();var s=map("item",p.getAsJsonObject("ingredient").get("item").getAsString(),"count",1);if(p.has("nbt"))s.put("nbt",p.get("nbt").getAsString());display.add(map("kind","stack","stack",s));}d.display.add(map("key","witchinggadgets:enchant_"+id,"class","modern","data",map("kind","infusion_enchantment","research","witchinggadgets:"+key,"enchantment",map("id",0,"name",enchant.getDescriptionId(),"max_level",enchant.getMaxLevel()),"recipeXP",xp,"instability",instability,"aspects",costs,"output",sequence(List.of()),"ingredients",sequence(display))));research.add(map("key","witchinggadgets:"+key,"category","WITCHGADG","displayColumn",x,"displayRow",y,"complexity",2,"aspects",researchAspects,"parents",List.of(id.equals("backstab")?"witchinggadgets:ENCH_STEALTH":"INFUSIONENCHANTMENT"),"isConcealed",true,"isSecondary",true,"pageCount",2,"icon_resource","witchinggadgets:textures/gui/research/icon_ench_"+icon+".png"));pages.add(map("key","witchinggadgets:"+key,"pages",List.of(text(key+".1"),recipe("INFUSION_ENCHANTMENT","enchant_"+id))));}
}
